var WENKU8 = (function () {
  var BASE = 'https://www.wenku8.net';
  function cookieOf(name) {
    var all = cookie.getCookie(BASE + '/');
    var m = all.match(new RegExp('(?:^|;\\s*)' + name + '=([^;]*)'));
    return m ? m[1] : '';
  }
  function credentials() {
    var user = source.get('wenku8_user');
    var pass = source.get('wenku8_pass');
    if (!user || !pass) {
      var raw = source.getVariable();
      if (raw) {
        try {
          var v = JSON.parse(raw);
          user = user || v.user || v.username || '';
          pass = pass || v.pass || v.password || '';
        } catch (e) {}
      }
    }
    return { user: user, pass: pass };
  }
  function loggedIn() {
    return !!(cookieOf('jieqiUserInfo') || cookieOf('jieqiUserName'));
  }
  function login() {
    if (loggedIn()) return true;
    var c = credentials();
    if (!c.user || !c.pass) {
      throw new Error('轻小说文库需要登录：先设置书源变量 wenku8_user / wenku8_pass');
    }
    var body = 'username=' + encodeURIComponent(c.user) +
      '&password=' + encodeURIComponent(c.pass) +
      '&usecookie=315360000&action=login&submit=' + encodeURIComponent('登录');
    var resp = java.post(BASE + '/login.php?do=submit', body, {
      'Referer': BASE + '/login.php',
      'Content-Type': 'application/x-www-form-urlencoded'
    });
    if (!loggedIn()) {
      throw new Error('轻小说文库登录失败（HTTP ' + resp.code + '）：检查 wenku8_user / wenku8_pass');
    }
    return true;
  }
  return { login: login, loggedIn: loggedIn };
})();
